/**
 * Renders react-email templates and 'sends' them by writing the draft to the log. No network egress.
 */
import { createLogger } from "@/lib/logger";

export type OutgoingEmail = {
  to: string;
  subject: string;
  html: string;
  text: string;
};

export type RenderedEmail = { subject: string; html: string; text: string };

export type EmailTemplate =
  | "invite"
  | "digest"
  | "mention"
  | "invoice"
  | "welcome"
  | "password-reset"
  | "overdue";

const logger = createLogger("email-service");

/** Subject lines per template; the props fill in the bracketed parts. */
const SUBJECTS: Readonly<Record<EmailTemplate, string>> = {
  invite: "You have been invited to a Taskflow workspace",
  digest: "Your Taskflow digest",
  mention: "You were mentioned in Taskflow",
  invoice: "Your Taskflow invoice",
  welcome: "Welcome to Taskflow",
  "password-reset": "Reset your Taskflow password",
  overdue: "You have overdue issues",
};

/**
 * "Sends" a message. Taskflow has no outbound mail transport by design — the
 * corpus must build and run offline — so delivery means writing the draft to
 * the structured log, where the dev tools tab surfaces it.
 */
export async function sendEmail(message: OutgoingEmail): Promise<void> {
  logger.info("email.sent", {
    to: message.to,
    subject: message.subject,
    bytes: message.html.length,
  });
}

/**
 * Renders a template to both an HTML and a plain-text body. The text half is
 * derived from the HTML rather than written twice, so the two can never drift.
 */
export async function renderEmail(
  template: EmailTemplate,
  props: Readonly<Record<string, unknown>>,
): Promise<RenderedEmail> {
  const subject = subjectFor(template, props);
  const html = renderBody(template, props);

  return { subject, html, text: toPlainText(html) };
}

function subjectFor(
  template: EmailTemplate,
  props: Readonly<Record<string, unknown>>,
): string {
  const base = SUBJECTS[template];
  const orgName = props.orgName;
  return typeof orgName === "string" ? `${base} — ${orgName}` : base;
}

function renderBody(
  template: EmailTemplate,
  props: Readonly<Record<string, unknown>>,
): string {
  const rows = Object.entries(props)
    .filter(([, value]) => value !== null && value !== undefined)
    .map(
      ([key, value]) =>
        `<tr><td>${escapeHtml(key)}</td><td>${escapeHtml(String(value))}</td></tr>`,
    )
    .join("");

  return [
    `<html><body><h1>${escapeHtml(SUBJECTS[template])}</h1>`,
    `<table>${rows}</table>`,
    "</body></html>",
  ].join("");
}

function toPlainText(html: string): string {
  return html
    .replace(/<\/(?:tr|h1|p|div)>/g, "\n")
    .replace(/<[^>]+>/g, " ")
    .replace(/[ \t]+/g, " ")
    .replace(/\n\s+/g, "\n")
    .trim();
}

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}
"use client";

/**
 * Bridges react-hook-form submission to a Server Action's `ActionResult`.
 *
 * Actions never throw for expected failures — they return
 * `{ ok: false, error }` so the form can render field errors without an error
 * boundary. This hook keeps that contract in one place: expected failures land
 * in `error`, and anything that genuinely throws is normalised by
 * `toAppError()` so the caller only ever sees an `AppErrorShape`.
 */
import { useCallback, useEffect, useRef, useState } from "react";
import { toAppError } from "@/lib/errors";
import type { ActionResult, AppErrorShape } from "@/types/api";

export type FormActionOptions = {
  onSuccess?: () => void;
  onError?: (error: AppErrorShape) => void;
  resetOnSuccess?: boolean;
};

export function useFormAction<TInput, TData>(
  action: (input: TInput) => Promise<ActionResult<TData>>,
  options?: FormActionOptions,
): {
  submit: (input: TInput) => Promise<void>;
  pending: boolean;
  error: AppErrorShape | null;
} {
  const [pending, setPending] = useState(false);
  const [error, setError] = useState<AppErrorShape | null>(null);

  // Callers pass an inline options object; a ref keeps `submit` stable so the
  // form does not re-register its handler on every render.
  const optionsRef = useRef(options);
  useEffect(() => {
    optionsRef.current = options;
  }, [options]);

  const submit = useCallback(
    async (input: TInput): Promise<void> => {
      const current = optionsRef.current;
      setPending(true);
      try {
        const result = await action(input);
        if (result.ok) {
          if (current?.resetOnSuccess !== false) setError(null);
          current?.onSuccess?.();
        } else {
          setError(result.error);
          current?.onError?.(result.error);
        }
      } catch (thrown) {
        const appError = toAppError(thrown);
        setError(appError);
        current?.onError?.(appError);
      } finally {
        setPending(false);
      }
    },
    [action],
  );

  return { submit, pending, error };
}
/**
 * Field-level validation message bound to an input.
 *
 * Owner A — design system. The id it renders is the one `Input` / `Textarea`
 * point at through `aria-errormessage`, which is why the convention
 * `${field}-error` lives in both files.
 */
import type { ReactElement } from "react";

export type ErrorMessageProps = { message?: string | null; fieldId?: string };

/** The id an invalid control should reference for `fieldId`. */
export function errorMessageId(fieldId: string): string {
  return `${fieldId}-error`;
}

export function ErrorMessage(props: ErrorMessageProps): ReactElement | null {
  const { message, fieldId } = props;

  // Rendering nothing is correct here: an empty live region would still be
  // announced by some screen readers on every re-render.
  if (message === undefined || message === null || message.trim() === "") {
    return null;
  }

  return (
    <p
      id={fieldId !== undefined ? errorMessageId(fieldId) : undefined}
      role="alert"
      className="mt-1 text-xs font-medium text-red-600"
    >
      {message}
    </p>
  );
}

